                            asyncio.set_event_loop(loop)
                            result = loop.run_until_complete(
                                company_knowledge.execute_autonomous_task(
                                    task_description=task_description,
                                    task_type=task_type,
                                    context=None
                                )
                            )
                            loop.close()
                            
